import { Text } from '@mantine/core';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { usePathname } from 'next/navigation';
import type { ReactNode } from 'react';
import { vi } from 'vitest';

import { CustomAppShell } from '@/components/CustomAppShell/CustomAppShell';
import type { AuthUserSummary } from '@/types/AuthUser';

type MockBurgerProps = {
    opened?: boolean;
    onClick?: () => void;
    hiddenFrom?: string;
} & React.ButtonHTMLAttributes<HTMLButtonElement>;

vi.mock('next/navigation', () => ({
    usePathname: vi.fn(() => '/'),
}));

vi.mock('@mantine/core', async (importOriginal) => {
    const actual = await importOriginal<typeof import('@mantine/core')>();

    const AppShell = Object.assign(
        ({
            children,
            navbar,
        }: {
            children?: ReactNode;
            navbar?: { collapsed?: { mobile?: boolean } };
        }) => (
            <div
                data-testid="app-shell"
                data-navbar-collapsed-mobile={String(
                    navbar?.collapsed?.mobile ?? false,
                )}
            >
                {children}
            </div>
        ),
        {
            Header: ({ children }: { children?: ReactNode }) => (
                <div data-testid="app-shell-header">{children}</div>
            ),
            Navbar: ({ children }: { children?: ReactNode }) => (
                <div data-testid="app-shell-navbar">{children}</div>
            ),
            Main: ({ children }: { children?: ReactNode }) => (
                <main>{children}</main>
            ),
        },
    );

    return {
        ...actual,
        AppShell,
        Badge: ({ children }: { children?: ReactNode }) => (
            <span>{children}</span>
        ),
        Burger: ({
            opened,
            onClick,
            hiddenFrom,
            ...props
        }: MockBurgerProps) => (
            <button
                {...props}
                data-hidden-from={hiddenFrom}
                data-opened={opened ? 'true' : undefined}
                onClick={onClick}
                type="button"
            />
        ),
        Container: ({ children }: { children?: ReactNode }) => (
            <div>{children}</div>
        ),
        Group: ({ children }: { children?: ReactNode }) => (
            <div>{children}</div>
        ),
        Image: ({ alt, src }: { alt?: string; src?: string }) => (
            <div
                aria-label={alt}
                data-src={src}
                role="img"
            />
        ),
        Stack: ({ children }: { children?: ReactNode }) => (
            <div>{children}</div>
        ),
        Text: ({ children }: { children?: ReactNode }) => (
            <span>{children}</span>
        ),
    };
});

vi.mock('@/components/NavBarNested/NavBarNested');

describe('CustomAppShell', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        vi.mocked(usePathname).mockReturnValue('/footy/results');
    });

    afterEach(() => {
        vi.restoreAllMocks();
    });

    it('renders app shell with header, navbar, and footer', () => {
        render(
            <CustomAppShell>
                <Text>Test Content</Text>
            </CustomAppShell>,
        );

        expect(screen.getByText('Toastboy FC')).toBeInTheDocument();
        expect(screen.getByText('Test Content')).toBeInTheDocument();
    });

    it('closes the mobile navbar when the pathname changes', async () => {
        const { rerender } = render(
            <CustomAppShell>
                <Text>Test Content</Text>
            </CustomAppShell>,
        );

        const burgerButton = screen.getByRole('button', {
            name: 'Toggle navigation',
        });
        fireEvent.click(burgerButton);

        expect(screen.getByTestId('app-shell')).toHaveAttribute(
            'data-navbar-collapsed-mobile',
            'false',
        );
        expect(burgerButton).toHaveAttribute('data-opened', 'true');

        vi.mocked(usePathname).mockReturnValue('/footy/fixtures');

        rerender(
            <CustomAppShell>
                <Text>Test Content</Text>
            </CustomAppShell>,
        );

        await waitFor(() => {
            expect(screen.getByTestId('app-shell')).toHaveAttribute(
                'data-navbar-collapsed-mobile',
                'true',
            );
            expect(
                screen.getByRole('button', { name: 'Toggle navigation' }),
            ).not.toHaveAttribute('data-opened');
        });
    });

    it('shows the dev mode badge when devMode is true', () => {
        render(
            <CustomAppShell devMode={true}>
                <Text>Content</Text>
            </CustomAppShell>,
        );

        expect(screen.getByText('dev mode')).toBeInTheDocument();
    });

    it('does not show the dev mode badge when devMode is not set', () => {
        render(
            <CustomAppShell>
                <Text>Content</Text>
            </CustomAppShell>,
        );

        expect(screen.queryByText('dev mode')).not.toBeInTheDocument();
    });

    it('passes the user prop to NavBarNested', () => {
        const user: AuthUserSummary = {
            name: 'Test User',
            email: 'test@example.com',
            playerId: 42,
            role: 'user',
        };

        render(
            <CustomAppShell user={user}>
                <Text>Content</Text>
            </CustomAppShell>,
        );

        expect(screen.getByText(/NavBarNested:/)).toBeInTheDocument();
        expect(screen.getByText(/test@example\.com/)).toBeInTheDocument();
    });

    it('renders the crest image', () => {
        render(
            <CustomAppShell>
                <Text>Content</Text>
            </CustomAppShell>,
        );

        expect(
            screen.getByRole('img', { name: 'Toastboy FC Crest' }),
        ).toBeInTheDocument();
    });

    it('wraps the crest image in a link to /footy', () => {
        render(
            <CustomAppShell>
                <Text>Content</Text>
            </CustomAppShell>,
        );

        const crest = screen.getByRole('img', { name: 'Toastboy FC Crest' });
        expect(crest.closest('a')).toHaveAttribute('href', '/footy');
    });
});

